    # 12
    h.append(H3('12. Riesgos, tesis contraria y factores de ruptura'))
    h.append(P(f'<strong>Tesis contraria (a favor de comprar hoy):</strong> el ecosistema es más valioso que lo que modelamos; la IA en el dispositivo desata un superciclo de renovación; Servicios crece 15 % o más con márgenes de plataforma; y el mercado, correctamente, paga múltiplos mayores que su historia porque el flujo es de altísima calidad y el costo de capital de largo plazo es menor que nuestro 8,25 %. En ese caso la Optimista ({usd(vo)}) sería el caso central y no el techo. Nuestra respuesta: aun la Optimista, con 40 % de margen y 8 % de crecimiento anual, queda por debajo del precio de {usd(px)}; la tesis contraria exige algo más que la Optimista.'))
    h.append(P('<strong>Riesgos principales:</strong> (1) regulatorio: comisiones de la tienda de aplicaciones y acuerdo de búsqueda, con riesgo judicial; (2) concentración en iPhone (53 % de los ingresos) y en la comparación difícil de FY2026; (3) China Ampliada y los aranceles; (4) costo de la IA: la I+D crece +32 % y la intensidad de capital podría subir; (5) múltiplos: el precio actual depende de que el mercado siga pagando 37,6x utilidades.'))
    h.append(table(['Historia','Disparadores de ruptura / cambio'],[
      ['Base','(1) ingresos de Servicios <+8 % dos trimestres seguidos; (2) margen operativo trimestral <33 %; (3) caída de la base instalada o de la tasa de renovación de iPhone.'],
      ['Conservadora','Fallo adverso firme contra comisiones de App Store o el acuerdo de búsqueda; ventas de iPhone en China Ampliada cayendo dos años; margen operativo <32 %.'],
      ['Optimista','Servicios >+15 % tres trimestres; ciclo de renovación de iPhone <3 años; nuevo producto con más de 20.000 M de ventas.']]))
    # 13
    h.append(H3('13. Catalizadores y plan de seguimiento'))
    h.append(UL([
      '<strong>Resultados trimestrales:</strong> crecimiento de Servicios, margen bruto de Servicios frente a hardware, iPhone en China Ampliada.',
      '<strong>Decisiones judiciales y regulatorias:</strong> comisiones de la tienda de aplicaciones y acuerdos de búsqueda (UE y EE. UU.).',
      '<strong>Costo de la IA:</strong> I+D como % de ventas (hoy 9,6 %) y capex (hoy 1,9 % de las ventas).',
      '<strong>Precio:</strong> la compra gradual empieza por debajo de ' + usd(146.70) + '; el precio de referencia con MOS es ' + usd(mos_price) + ' y debe reevaluarse cada trimestre con el nuevo 10-Q.',
      '<strong>Costo de capital:</strong> tasa libre (hoy 4,86 %); un descenso de 100 pb en el costo de capital inicial sube el valor Base cerca de 6 %, de 209,58 a 221,45 (matriz B).']))
    h.append(P('Próximo corte: el 10-Q del primer trimestre fiscal de 2027. Hasta entonces, esta revisión permanece EN_REVISION hasta cerrar la auditoría R6 y la verificación documental pendiente de FY2017–FY2023.'))
    # 14
    h.append(H3('14. Fuentes, limitaciones y estado del estudio'))
    h.append(P('<strong>Fuentes primarias:</strong> 10-K de Apple del ejercicio fiscal 2026 (XBRL de la SEC, <em>companyfacts</em>); portada del 10-K (acciones, 23-oct-2026). <strong>Contraste:</strong> FMP y Alpha Vantage (precio de cierre 6-nov-2026; estados); FRED DGS10 (tasa libre); Damodaran (prima de riesgo madura, primas por país, medias de industria, calificaciones sintéticas).'))
    h.append(P('<strong>Limitaciones declaradas:</strong> (1) auditoría económica independiente R6 no realizada; (2) verificación documental FY2017–FY2023 pendiente; (3) gasto por intereses estimado; (4) participación de mercado N/D; (5) pagos de Google no verificados; (6) gobierno y compensación no analizados; (7) las matrices 5×5 por múltiplo se derivan de las hojas de método (precio FY+3 descontado con el Ke Base) y la hoja conserva el precio FY+3 sin descontar; (8) QA visual de la app pendiente.'))
    h.append(P(f'<strong>Estado:</strong> EN_REVISION. La app y los validadores reconocen el contrato Reboot (jmr-reboot-3libros-v1); no se declara la valoración como auditada.'))
    return ''.join(h)
